# ============================================================
# AEGIS NIDS - Phase 28 Deploy Script (Complete Golden Path)
# ============================================================
$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS Phase 28 - Complete Golden Path"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param([string]$RelativePath, [string]$Base64Content, [int]$ExpectedLines)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $BackupPath = "$FullPath.phase28_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
        Write-Host "  [OK] Backup created"
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] Line count: actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] Deployed: $ActualLines lines (expected $ExpectedLines)"
    }
}

$B64_1 = ''
Deploy-File -RelativePath "core/nids_main.zig" -ExpectedLines 147 -Base64Content $B64_1

$B64_2 = ''
Deploy-File -RelativePath "core/nids_capture.zig" -ExpectedLines 233 -Base64Content $B64_2

$B64_3 = ''
Deploy-File -RelativePath "core/windows_capture.zig" -ExpectedLines 187 -Base64Content $B64_3

$B64_4 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2227 -Base64Content $B64_4


Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS"
} else {
    Write-Host "[BUILD] FAILED"
    exit 1
}

Write-Host ""
Write-Host "[INFO] Run tests: zig build test"
Write-Host "[INFO] Expected: 90 tests passed"
Write-Host ""
Write-Host "=== GOLDEN PATH COMPLETE ==="
Write-Host "Sensor -> createEvent -> submitEvent -> PriorityQueue -> popEvent -> ForensicLog"
Write-Host "         -> Detection -> Policy -> PEP -> ForensicLog"
Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 28 changes (Complete Golden Path - Sensor → Queue → Detection → Policy):"
Write-Host "    FABRIC-INIT: nids_main.zig: Added nose.initFabric() + shutdownFabric()"
Write-Host "                 (Event Fabric initialized at startup with 256 capacity/queue)"
Write-Host "    SENSOR-WIRE: nids_capture.zig: Pipe sensor submits events to Event Fabric"
Write-Host "                 BEFORE calling inspect_packet() (creates forward event)"
Write-Host "    SENSOR-WIRE: windows_capture.zig: WFP sensor submits events to Event Fabric"
Write-Host "                 with source_ip, source_port, protocol, layer_id"
Write-Host "    DRAIN-THREAD: nids_analyze.zig: New eventFabricDrain() thread"
Write-Host "                  - Pops events from Nose Contract queue"
